(function(window){'use strict';const DB_NAME='EXS_UT99_ASSET_CACHE_V1';const STORE_NAME='game_files';const DB_VERSION=1;class UT99AssetCache{constructor(){this.db=null;this.manifest=null;this.isReady=false;this.onProgress=null;}
async init(){return new Promise((resolve,reject)=>{if(!window.indexedDB){console.warn('IndexedDB not available, cache disabled.');this.isReady=false;return resolve(false);}
const request=indexedDB.open(DB_NAME,DB_VERSION);request.onupgradeneeded=(e)=>{const db=e.target.result;if(!db.objectStoreNames.contains(STORE_NAME)){db.createObjectStore(STORE_NAME);}};request.onsuccess=(e)=>{this.db=e.target.result;this.isReady=true;resolve(true);};request.onerror=(err)=>{console.error('IndexedDB open error:',err);this.isReady=false;resolve(false);};});}
async getCachedFile(filePath){if(!this.isReady||!this.db)return null;return new Promise((resolve)=>{try{const tx=this.db.transaction([STORE_NAME],'readonly');const store=tx.objectStore(STORE_NAME);const req=store.get(filePath.toLowerCase());req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>resolve(null);}catch(e){resolve(null);}});}
async saveCachedFile(filePath,arrayBuffer){if(!this.isReady||!this.db)return false;return new Promise((resolve)=>{try{const tx=this.db.transaction([STORE_NAME],'readwrite');const store=tx.objectStore(STORE_NAME);store.put(arrayBuffer,filePath.toLowerCase());tx.oncomplete=()=>resolve(true);tx.onerror=()=>resolve(false);}catch(e){resolve(false);}});}
async fetchFileWithProgress(url,filePath,expectedSize=0){const cached=await this.getCachedFile(filePath);if(cached){return cached;}
const response=await fetch(url);if(!response.ok){throw new Error(`Failed to download ${filePath}:HTTP ${response.status}`);}
const contentLength=response.headers.get('Content-Length');const total=contentLength?parseInt(contentLength,10):expectedSize;let loaded=0;const reader=response.body.getReader();const chunks=[];while(true){const{done,value}=await reader.read();if(done)break;chunks.push(value);loaded+=value.length;if(this.onProgress&&total>0){this.onProgress(filePath,loaded,total);}}
const fullBuffer=new Uint8Array(loaded);let offset=0;for(const chunk of chunks){fullBuffer.set(chunk,offset);offset+=chunk.length;}
await this.saveCachedFile(filePath,fullBuffer.buffer);return fullBuffer.buffer;}
async loadManifest(manifestUrl='/games/ut99/manifest.json'){try{const res=await fetch(manifestUrl);if(res.ok){this.manifest=await res.json();return this.manifest;}}catch(e){console.warn('Custom manifest not found, using fallback asset structure.');}
return null;}
async clearCache(){if(!this.isReady||!this.db)return;const tx=this.db.transaction([STORE_NAME],'readwrite');tx.objectStore(STORE_NAME).clear();}}
window.UT99AssetCache=new UT99AssetCache();})(window);